import {g} from './shared.js';
export const systemGuides=[
g('world-model','要选择行动，常需判断“这样做之后会发生什么”。世界模型学习环境变化或未来观测的分布，为预测、规划或表征学习提供信息。',
 ['出门前估计“现在走这条路，十分钟后会到哪”，再据此选路。','模型预测可能错误；生成逼真的视频不自动等于理解可控动力学。'],
 ['简化状态是位置 x 和速度 v，动作 a 是加速度指令。','学习 (x,v,a)→下一状态，与“不动”或“保持速度”基线比较。','自由滚动多步后再用于规划，检查误差是否让计划失效。'],
 ['先定义时间间隔、观测与动作契约。','按 episode 划分，训练并评估一步和多步。','检查干预动作能否改变预测，再测下游闭环。'],
 '可复用环境预测来比较行动、辅助规划或学习状态表示。','误差会累积，分布外行动可能被错误预测；架构名字不能保证预测具备因果意义。',
 ['会续写视频就足以当机器人世界模型吗？','不一定，还要看动作条件、时间一致性、干预预测和闭环验证。']),
g('embodied-model','仅生成语言不足以处理传感器、动作和真实环境反馈。具身模型围绕感知与行动任务建模，通常需要与控制、执行和验证系统配合。',
 ['懂菜谱与实际拿锅炒菜不同：还要看到物体、决定动作、感知变化并纠错。','“具身”不是一种固定网络层，也不保证必须使用某个大语言模型。'],
 ['输入相机、关节状态和任务，输出动作或子目标。','动作需要单位、频率、范围和时间对齐。','在环境里执行后看任务是否完成，而不是只看输出看起来合理。'],
 ['定义具体身体/环境接口与任务。','从简单策略、感知和控制基线开始。','分开验证模块误差、轨迹行为和闭环成功。'],
 '把视觉、语言和行动连接起来，可解决实际交互任务。','数据昂贵、分布变化与误差代价大；离线指标不足以覆盖真实任务。',
 ['具身模型一定等于世界模型吗？','不是，它可以包含策略、感知、预测等不同模块；世界模型只是可能的一部分。']),
g('embodied-brain','复杂任务需要把高层指令分解为可执行子目标。“具身大脑”常指这种高层决策角色，但具体边界由系统定义。',
 ['“收拾桌面”先拆成识别物品、逐个搬走和检查；手臂控制器负责具体运动。','这个系统称呼没有唯一标准结构，不能从“大脑”一词推断内部能力。'],
 ['大脑输出“先移动红块”，动作层执行对应目标。','反馈显示未到达，大脑不能仅凭自己说成功推进。','大脑可先用规则实现，验证协议后再比较语言模型方案。'],
 ['明确高层输入、子目标 schema 与权限边界。','定义低层动作接口、工具反馈和失败处理。','分别测计划质量与实际成功，避免只评文本。'],
 '分层便于复用底层技能、解释任务流程和定位错误。','子目标不可执行、感知不确定或反馈丢失都会破坏闭环；名称不是能力证据。',
 ['大脑回答“完成”，就应结束任务吗？','不应，需环境或工具验证器给出相应完成证据。']),
g('policy','世界模型可以预测不同动作的后果，却不一定直接选择动作。策略定义给定可用信息后该采取什么行为，是决策的直接接口。',
 ['导航软件可能直接建议下一步左转；预测拥堵和选择转向是两个职责。','策略可以是规则、概率分布或神经网络，不限于一种训练法。'],
 ['状态 s 下，动作 left/right 概率为 [0.8,0.2]。','训练可来自示范、奖励或其他信号，部署可采样或取确定动作。','动作执行改变状态，下一步要用新观测重新决策。'],
 ['定义观测/历史、动作空间和输出单位。','选择行为克隆等简单基线。','在闭环评测成功、代价与失败模式。'],
 '推理可直接输出行为，接口清楚、易连接执行器。','训练分布之外可能失效；高概率不代表动作安全或适合当前环境。',
 ['policy 一定经过强化学习吗？','不一定，行为克隆和手写规则也能形成策略。']),
g('action-conditioning','同一个当前位置，采取不同动作应有不同未来。若预测器不接收动作，就可能只能学数据里平均发生的变化，难以评估候选行动。',
 ['看到汽车在路口，不知道司机左转还是右转，就很难预测下一条街的位置。','输入动作只是提供条件，不自动保证模型学到可干预的因果关系。'],
 ['当前位置 x=0，动力学 x_next=x+a。','a=1 时目标为 1，a=-1 时为 -1。','不输入 a 的均方回归可能预测 0，两种动作都不正确。'],
 ['按真实时间对齐观测、动作和后续目标。','检查动作缩放、延迟和执行频率。','固定状态只改动作，测试预测是否合理改变。'],
 '支持比较不同动作后果，是模型规划的重要接口。','动作覆盖不足、时延错位或数据相关性会导致错误反事实预测。',
 ['模型接了 action tensor，就证明它使用动作了吗？','没有，需要换动作对照和独立环境验证。']),
g('rollout','单步预测总从真实状态开始，不能暴露模型错误被反复喂回的后果。rollout 将预测或策略执行连续展开，观察随时间累积的行为。',
 ['每步都让老师纠正位置，与自己沿估计路线走十步，终点误差可能完全不同。','rollout 在世界预测和 RL 中语境不同，分别要说明是模型展开还是环境交互采样。'],
 ['真实每步位置加 1，模型每步误加 1.1。','自由运行 10 步误差累积到 1.0；若每步重置到真值，看到的只是 0.1。','比较 horizon=1/4/8 的指标，并固定初始真实前缀。'],
 ['说明初始输入与哪些后续观测是真实的。','保持时间、动作和停止条件一致。','记录误差随 horizon、闭环成功与失败场景。'],
 '揭示长期稳定性与部署分布，能发现单步指标隐藏的问题。','长轨迹更难归因，误差、策略和环境反馈相互影响；不能偷偷接回真实未来。',
 ['每一步都换成真实状态仍叫自由 rollout 吗？','不是，这更接近逐步使用真实历史的评测。']),
g('bc','有专家观测—动作示范时，可以先学习直接模仿，避免一开始就设计奖励和大规模探索。行为克隆把策略学习变成监督学习。',
 ['观察师傅在每种路况如何打方向，学习看到相似情况时怎样转。','师傅演示中没出现偏离道路后的状态，学生部署时仍可能遇到。'],
 ['样本为 (观测 s,专家动作 a)，训练策略预测 a。','离线误差小，却因一次小偏差进入未见状态，后续动作更差。','因此还要在环境里从不同初始条件闭环测试。'],
 ['检查示范质量、动作单位与时间对齐。','按轨迹划分，训练并比较简单基线。','分析闭环分布偏移，必要时补充纠错状态数据。'],
 '目标直接、实现相对简单，是机器人策略的有用起点。','依赖示范覆盖，多解动作均值可能无效，误差会改变部署时的状态分布。',
 ['BC 验证动作 MSE 很低就证明任务成功吗？','不证明，必须看连续执行后的环境结果。']),
g('vla','机器人任务同时依赖看到什么、用户说什么和如何动作。VLA 将视觉、语言与动作接口放进一个学习系统，让任务条件参与策略生成。',
 ['“把红杯放左边”需要看见红杯、理解左边，并产生对应动作，而不只是描述画面。','VLA 不是唯一结构；动作可连续、离散、分块或由不同头预测。'],
 ['视觉塔输出图像特征，文字编码提供任务。','骨干融合后，动作头输出约定的动作表示。','改变文字或目标图像应改变动作，需反事实对照验证。'],
 ['明确视觉、语言、本体状态和动作的时间/单位协议。','核对哪些模块预训练、冻结或适配。','独立测语言遵循、感知和闭环任务成功。'],
 '共享多模态表征，可用语言条件组织多任务行为。','数据与接口复杂，任务捷径可能让某模态被忽略；语言流畅不证明动作有效。',
 ['能看图聊天的 VLM 自动就是 VLA 吗？','不是，还需动作表示、训练目标、执行接口与闭环验收。']),
g('diffusion-policy','相似观测可能有多种可行动作序列，直接平均回归会产生不合理中间动作。Diffusion Policy 用条件去噪生成动作或动作块分布。',
 ['绕障碍可左绕也可右绕，把两条路线逐点平均可能正撞障碍；需要生成一种一致的选择。','扩散生成动作不自动处理全部动力学和约束，还需执行与反馈。'],
 ['观测作为条件，对真实动作块加噪。','训练网络预测去噪目标，推理从噪声得到一段动作。','通常只执行其中一部分，再用新观测重规划，减少长开环误差。'],
 ['核对动作归一化、horizon 和观测历史。','记录采样步数与控制时延。','比较行为克隆基线、动作多样性与闭环成功。'],
 '能表达多峰动作分布，并建模动作块内部关系。','多步采样有延迟，分块长度与执行频率影响闭环；机制 Flow 示例不等于完整策略复现。',
 ['生成整段动作后必须全部无反馈执行吗？','不必，常采用滚动时域方式执行前段并重新观察。']),
g('planning','直接策略未必能权衡不同动作后果。规划显式比较候选行动或轨迹，结合目标与预测模型选择更合适的方案。',
 ['出门前比较几条路线的时间与拥堵，选择其中一条，途中再根据交通更新。','计划好坏依赖预测准确度；把代价算得很精确也不能消除错误世界模型。'],
 ['从当前状态采样三条动作序列。','世界模型 rollout 预测，按目标距离与动作成本打分。','选择最好候选并执行第一步，再重新观察；随机 shooting 不保证全局最优。'],
 ['定义目标/约束、候选生成和预测时域。','与零动作、随机、简单策略等基线比较。','记录模型误差、搜索预算、时延与闭环成功。'],
 '能在不重新训练策略的情况下按目标比较候选，便于加入代价。','搜索昂贵、模型误差可被规划利用，长时域不一定更好。',
 ['世界模型的最低预测代价方案一定在环境中最好吗？','不是，预测偏差可能让规划选中虚假的好方案。']),
g('closed-loop','离线预测不影响下一条评测输入，但真实行动会改变环境。闭环评测把动作执行与后续观测连起来，检验完整任务过程。',
 ['背出驾驶操作和实际开一段路不同；每次转向都会改变下一秒所处位置。','模拟闭环结果也只适用于相应模拟条件，不能直接外推真实环境。'],
 ['观测→策略→动作→环境→新观测。','一次偏离引发后续分布变化，记录是否能恢复。','最终报告任务成功率、步数、代价与失败，而不只报每步动作误差。'],
 ['固定初始场景、任务和预算。','明确定义环境验证的成功/失败条件。','增加扰动与故障测试，保留完整轨迹用于诊断。'],
 '能评价部署时的反馈和误差累积，连接模块指标与真正任务。','耗时且受环境影响，需要重复场景与可靠验证；挑选成功视频会严重误导。',
 ['模型说“已抓取”能作为成功标签吗？','应由环境或独立传感验证，不能只信模型输出。']),
g('agentic','复杂任务需要多步检索、调用工具与更新状态，一次生成回答不够。Agent 循环把模型建议接到可执行协议和反馈验证。',
 ['助理先查库存、再下单、最后核实订单；每一步都依赖工具结果，而不是只写一份想象中的执行报告。','Agent 是系统组织方式，不自动意味着多个模型、自治权限或参数训练。'],
 ['目标 [red,blue]，当前请求 r1/red。','返回 r0/red 即使标成功，也不能推进当前任务。','只有 r1/red 且独立 verified=True 才转到 blue；超预算或故障则终止。'],
 ['定义工具 schema、请求归属、任务状态和预算。','区分检索文本、模型推断与工具事实。','测试过期返回、错误参数、卡住和重试。'],
 '把生成能力用于多步任务，可接外部知识和执行工具。','错误会跨步传播，工具调用有成本；口头完成、检索到资料都不等于成功或训练完成。',
 ['增加 RAG 就等于做了 SFT 吗？','不是，检索增加推理上下文，SFT 改变可训练参数。'])
];
